/**
 * @file pusch_e2e_launch.cuh
 * @brief Kernel launch wrappers: thin host-callable functions that perform the CUDA
 * kernel launches (and compile-time template dispatch) for the PUSCH E2E
 * kernels
 * 
 * Declared here, defined in pusch_e2e.cu (the kernels TU) because a
 * kernel can only be launched from the TU that defines it. The host API TU
 * (pusch_e2e_api.cu) calls these instead of launching kernels directly
 */

